// Used only by the server-rendered reference article.
import type { Locale } from '../types';
import { articleSections, pageArticles } from './pageArticles.mjs';

type GuideCopy = {
  title: string; intro: string; reference: string; contents: string;
  links: Record<string, string>;
  sections: [string, string, string][];
};

const copies: Record<Exclude<Locale, 'en'>, GuideCopy> = {
  es: {
    title: 'Guía práctica de privacidad para los datos de tu cuenta y tus textos',
    intro: 'La política anterior describe el servicio. Estas explicaciones te ayudan a entender cómo circulan los datos y qué opciones ofrece la interfaz. No prometen normas de conservación de los proveedores que no se hayan verificado ni sustituyen sus condiciones de privacidad.',
    reference: 'Referencia práctica', contents: 'En esta guía',
    links: { '/privacy': 'Leer la política de privacidad →', '/account': 'Gestionar tu cuenta', '/guides': 'Leer las guías →', '/terms': 'Leer las condiciones →', '/features': 'Ver las funciones →', '/dashboard': 'Abrir el espacio de escritura', '/about': 'Acerca del servicio →' },
    sections: [
      ['Dónde pueden existir tus datos', 'Los datos del formulario sirven para preparar una solicitud a la IA. Las solicitudes y respuestas de usuarios que han iniciado sesión se guardan automáticamente en el historial privado; las preferencias del perfil se guardan cuando las confirmas. Los archivos de texto y PDF descargados quedan en tu dispositivo. Cambiar o borrar una copia no modifica las demás.', 'Editar una respuesta no actualiza el PDF descargado ni la respuesta original del historial. Copia o exporta los cambios antes de salir. Una conversación de investigación conserva preguntas, respuestas y enlaces disponibles; no guarda el currículum original, aunque puede incluir texto extraído de adjuntos. Las conversaciones permanecen en la base de datos hasta que las borras: cerrar el navegador no las elimina.'],
      ['Proporciona solo el contexto personal necesario', 'Una solicitud suele necesitar tu nombre o firma, experiencia relevante y detalles de la oportunidad, no tu dirección completa, documento de identidad ni información financiera. Sustituye los datos ajenos al objetivo por una descripción breve. Revisa todo archivo antes de subirlo, incluidas páginas antiguas y comentarios.', 'Un resumen breve con ejemplos sólidos suele ser más útil que un historial sin filtrar. Guarda en el perfil solo habilidades y experiencia pertinentes. En notas de investigación, conserva la URL oficial y lo que verificaste, no documentos de otros candidatos. Usa un nombre público en las reseñas y omite datos confidenciales.'],
      ['Protege la información que decides introducir', 'No incluyas números de pasaporte, datos bancarios, historiales médicos ni contraseñas en las instrucciones. Elimina del currículum lo que no quieras que procese un proveedor de IA o utiliza un resumen. Revisa las capturas para quitar direcciones privadas y mensajes ajenos a la solicitud.', 'Neon Auth gestiona el acceso y las API protegidas verifican la identidad antes de leer o modificar documentos. El servidor limita las operaciones a su propietario, pero ningún servicio garantiza seguridad perfecta. Usa una contraseña exclusiva, cierra sesión en dispositivos compartidos y guarda las descargas en un lugar que controles. Pide permiso antes de incluir datos de otra persona o exclúyelos.'],
      ['Considera por separado el tratamiento por terceros', 'El servicio utiliza proveedores para alojamiento, autenticación, base de datos, IA y pagos con criptomonedas cuando están habilitados. Las rutas de generación pueden usar Puter y Google Gemini según el flujo disponible; Neon proporciona autenticación y base de datos, y NOWPayments gestiona pagos. Enviar una solicitud a la IA y guardar un borrador en el historial son operaciones distintas.', 'Consulta las condiciones de cada proveedor: sus normas de conservación y entrenamiento dependen del servicio, la cuenta y la ruta. No supongas que todos borran las solicitudes inmediatamente. Verifica los acuerdos de tratamiento o autorizaciones de tu organización antes de enviar información sensible. Un resumen reduce la exposición; la disponibilidad de los proveedores puede cambiar.'],
      ['Gestiona los borradores locales en dispositivos compartidos', 'Las sesiones guardadas localmente pertenecen al mismo navegador y no se sincronizan automáticamente entre equipos. Quien use el mismo perfil del navegador podría acceder a ellas. La navegación privada o la limpieza del navegador pueden borrarlas; cambiar de navegador no las traslada. Exporta el trabajo que no quieras perder.', 'El historial de la cuenta permite reabrir nuevas solicitudes y respuestas en otro dispositivo. Los borradores locales antiguos no se suben ni migran automáticamente y no existe un gestor separado de sesiones guardadas. Para limpiar un equipo compartido, usa los controles de datos del navegador y los archivos del dispositivo tras guardar lo necesario. Cerrar sesión, borrar datos locales y borrar PDF son acciones distintas.'],
      ['Mantén privadas tus credenciales de acceso y pago', 'Tu contraseña pertenece al servicio de autenticación, nunca a las instrucciones, documentos, reseñas o mensajes de soporte. El navegador obtiene un token firmado de corta duración y el servidor lo verifica para acceder a datos protegidos. Una identidad válida no autoriza a leer documentos ajenos: también se comprueba la propiedad de los recursos.', 'Nunca compartas claves privadas ni frases de recuperación de una cartera. El pago integrado no requiere esas frases. Describe incidencias con una referencia de pedido no sensible o una captura que oculte credenciales. La URL pública de autenticación no es una clave secreta; las claves de proveedores deben permanecer en el servidor y fuera de campos o contenido públicos.'],
      ['Organiza las conversaciones y respuestas', 'Pon títulos que identifiquen la organización o el programa y el propósito. La barra lateral muestra las conversaciones privadas disponibles según tu acceso, incluidas las de los flujos de cartas y de investigación habilitados. Puedes abrirlas, renombrarlas o continuarlas. Las conversaciones anteriores se cargan en grupos de veinte y los resultados permiten cargar mensajes anteriores. No hay una biblioteca manual separada de borradores ni una acción para guardarlos en la cuenta.', 'Las nuevas solicitudes guardan automáticamente el resumen y la respuesta. Las copias locales antiguas no se suben sin avisar. Conserva las fuentes y las verificaciones en las notas de investigación, elimina borradores innecesarios y descarga los documentos finales importantes. El historial no demuestra que una solicitud se haya enviado, aceptado o revisado: lleva tu propio registro de esos eventos.'],
      ['Reutiliza tu perfil sin perder la personalización', 'El perfil puede guardar nombre, habilidades, experiencia, idioma de salida y tono preferidos para evitar repetirlos. Mantenlos actualizados y verificables: explica tus herramientas, capacidades y aportaciones. No guardes contraseñas, números de identidad, datos bancarios ni material confidencial ajeno al objetivo.', 'El perfil es un punto de partida. Adapta los ejemplos a cada oportunidad y revisa experiencias al terminar un curso, empleo o proyecto para no presentar información antigua como actual. Cierra sesión en equipos compartidos y recuerda que pueden quedar borradores locales. La configuración de cuenta y el almacenamiento del navegador se gestionan por separado.'],
      ['Gestiona las copias que has guardado', 'Borrar una conversación elimina sus mensajes asociados y el servidor solo permite hacerlo a su propietario. No elimina archivos descargados ni datos locales antiguos: bórralos con las herramientas del dispositivo y del navegador. Revisa los mensajes anteriores y conserva la versión final que necesites antes de borrar.', 'La eliminación de toda la cuenta se solicita a soporte; esta versión no ofrece un botón automático. Escribe a support@ailettergen.com desde el correo de la cuenta sin incluir tu contraseña. Los pagos y las copias de seguridad pueden requerir un tratamiento distinto. No prometemos una eliminación inmediata en todos los sistemas de terceros; especifica qué información deseas eliminar.'],
      ['Convierte tu experiencia en ejemplos útiles', 'Explica lo que hiciste, en qué situación y por qué importa al destinatario. En lugar de afirmar que te comunicas bien, describe cómo resolviste preguntas de clientes o explicaste un problema. Usa cifras solo si puedes verificarlas. Proyectos, voluntariado y estudios también aportan ejemplos válidos.', 'Relaciona cada requisito con una prueba y su utilidad para la oportunidad. Elige dos o tres conexiones fuertes y comprueba que el texto no exagere tu contribución: ayudar a preparar algo no equivale a dirigir un departamento. Debes reconocer tu experiencia real en cada párrafo.'],
      ['Comparte solo información que tengas derecho a usar', 'Un currículum o una captura puede incluir datos de otras personas. Evita documentos confidenciales de empleadores, mensajes privados o solicitudes ajenas. Describe tu aportación al trabajo conjunto sin atribuirte todo el mérito. Cita requisitos solo en la medida necesaria, sin reproducir documentos protegidos completos.', 'Revisa nombres, organizaciones, citas y afirmaciones del borrador. Elimina detalles plausibles que no puedas verificar. En solicitudes académicas, respeta las normas de la institución sobre ayuda externa e IA. La herramienta apoya una redacción honesta, no la suplantación ni la presentación engañosa de una candidatura.'],
      ['Contrasta la investigación universitaria con fuentes oficiales', 'Los plazos, tasas, becas, documentos y programas cambian entre convocatorias. Abre las fuentes oficiales y verifica el curso académico, tu nacionalidad, nivel y modalidad. Un resumen de IA organiza información, pero no es una decisión de admisión. Si una afirmación importante carece de fuente, considérala pendiente.', 'Anota la URL del programa, tu pregunta y los hechos verificados. Distingue entre un requisito publicado y tu interpretación de si lo cumples. Si dos páginas oficiales se contradicen, consulta a admisiones. Vuelve a comprobar fechas y tasas antes de usarlas. El acceso a investigación de un plan previsto no garantiza la admisión.'],
      ['Elige entre PDF, texto y contenido copiado', 'Descarga texto para seguir editando, copia para formularios o correos y usa PDF cuando se admita un archivo con diseño estable. Sigue las instrucciones del destinatario y revisa el archivo real: saltos de página, firma y caracteres de idiomas no latinos.', 'Pon un nombre de archivo que identifique la candidatura sin datos personales innecesarios ni nombres de otra organización. La descarga es independiente del borrador y la copia de la cuenta. Tras editar, exporta de nuevo y adjunta la versión correcta.'],
      ['Vuelve a comprobar la información con el tiempo', 'Las funciones, rutas de modelos, precios y datos universitarios pueden cambiar. Distingue lo disponible de lo previsto y consulta las fuentes oficiales antes de basar una compra o solicitud en una comparación o nota antigua.', 'La política y las condiciones también pueden cambiar con el almacenamiento o las funciones de cuenta. Si la descripción no coincide con la interfaz, consulta a soporte y evita enviar información sensible innecesaria mientras se aclara. Revisa los borradores cuando cambie el contexto de la candidatura.'],
    ],
  },
  fr: {
    title: 'Guide pratique de confidentialité des données de compte et de rédaction',
    intro: 'La politique ci-dessus décrit le service. Ces explications vous aident à comprendre les flux de données et les choix disponibles dans l’interface. Elles ne promettent aucune règle de conservation non vérifiée et ne remplacent pas les conditions de confidentialité des prestataires.',
    reference: 'Référence pratique', contents: 'Dans ce guide',
    links: { '/privacy': 'Lire la politique de confidentialité →', '/account': 'Gérer votre compte', '/guides': 'Lire les guides →', '/terms': 'Lire les conditions →', '/features': 'Voir les fonctionnalités →', '/dashboard': 'Ouvrir l’espace de rédaction', '/about': 'À propos du service →' },
    sections: [
      ['Comprendre les différents emplacements de vos données', 'Les données du formulaire servent à préparer une demande à l’IA. Les demandes et réponses des utilisateurs connectés sont automatiquement conservées dans l’historique privé ; les préférences de profil le sont lorsque vous les enregistrez. Les téléchargements de texte et de PDF restent sur votre appareil. Modifier ou supprimer une copie ne modifie pas les autres.', 'Modifier une réponse ne réécrit ni un PDF téléchargé ni la réponse d’origine dans l’historique. Copiez ou exportez vos modifications avant de partir. Une conversation de recherche conserve questions, réponses et liens disponibles, pas le CV original, mais peut inclure du texte extrait des pièces jointes. Les conversations restent en base jusqu’à leur suppression : fermer le navigateur ne les efface pas.'],
      ['Ne fournir que le contexte personnel nécessaire', 'Une demande nécessite généralement votre nom ou signature, une expérience pertinente et des détails sur l’opportunité, rarement votre adresse complète, votre numéro d’identité ou des données financières. Remplacez les détails inutiles par un résumé. Examinez chaque fichier entier avant de l’importer, y compris les anciennes pages et les commentaires.', 'Un bref descriptif accompagné d’exemples solides est souvent plus utile qu’un historique non filtré. Limitez le profil aux compétences pertinentes. Dans les notes de recherche, conservez l’URL officielle et vos vérifications plutôt que les documents d’un autre candidat. Pour un avis public, utilisez un nom d’affichage et omettez les détails confidentiels.'],
      ['Protéger les informations que vous saisissez', 'N’incluez ni numéro de passeport, ni coordonnées bancaires, ni dossier médical, ni mot de passe dans vos instructions. Retirez du CV ce que vous ne voulez pas faire traiter par l’IA ou fournissez un résumé. Vérifiez les captures pour retirer adresses privées et messages sans rapport.', 'Neon Auth gère l’accès et les API protégées vérifient l’identité avant toute lecture ou modification. Le serveur limite les opérations au propriétaire, mais aucun service ne garantit une sécurité parfaite. Utilisez un mot de passe unique, déconnectez-vous sur les appareils partagés et protégez vos téléchargements. Demandez l’autorisation avant d’inclure les informations d’autrui, ou omettez-les.'],
      ['Examiner séparément le traitement par des tiers', 'Le service utilise des prestataires pour l’hébergement, l’authentification, la base de données, l’IA et les paiements en cryptomonnaies lorsqu’ils sont activés. Les routes de génération peuvent utiliser Puter et Google Gemini selon le processus disponible ; Neon fournit l’authentification et la base de données, et NOWPayments traite les paiements. L’envoi à l’IA et l’enregistrement dans l’historique sont distincts.', 'Consultez chaque prestataire : ses règles de conservation et d’entraînement dépendent du service, du compte et de la route. Ne supposez pas une suppression immédiate universelle. Vérifiez les accords de traitement ou autorisations de votre organisation avant un envoi sensible. Un résumé limite l’exposition ; la disponibilité des prestataires peut changer.'],
      ['Gérer les brouillons locaux sur un appareil partagé', 'Les sessions locales appartiennent au même navigateur et ne se synchronisent pas automatiquement entre ordinateurs. Toute personne utilisant le même profil peut éventuellement les ouvrir. La navigation privée ou le nettoyage du navigateur peut les supprimer ; changer de navigateur ne les transfère pas. Exportez les travaux importants.', 'L’historique du compte permet de rouvrir les nouvelles demandes et réponses sur un autre appareil. Les anciens brouillons locaux ne sont ni importés ni migrés automatiquement ; il n’existe pas de gestionnaire séparé de sessions enregistrées. Nettoyez les données du navigateur et les fichiers de l’appareil après avoir sauvegardé le nécessaire. Déconnexion, suppression locale et suppression d’un PDF sont des actions distinctes.'],
      ['Garder vos identifiants de connexion et de paiement privés', 'Votre mot de passe appartient au service d’authentification, jamais aux instructions, documents, avis ou messages au support. Le navigateur obtient un jeton signé de courte durée, vérifié par le serveur pour accéder aux données protégées. Une identité valide n’autorise pas l’accès aux documents d’autrui : leur propriété est aussi vérifiée.', 'Ne partagez jamais les clés privées ou phrases de récupération d’un portefeuille. Le paiement intégré ne les demande pas. Décrivez une erreur avec une référence de commande non sensible ou une capture masquant les identifiants. L’URL publique d’authentification n’est pas une clé secrète ; les secrets des prestataires restent sur le serveur, hors des contenus et champs publics.'],
      ['Organiser les conversations et les réponses', 'Choisissez un titre indiquant l’organisation ou le programme et l’objectif. La barre latérale affiche les conversations privées disponibles selon votre accès, y compris les processus de lettres et de recherche activés. Ouvrez, renommez ou poursuivez une conversation. Les anciennes conversations se chargent par lots de vingt ; les résultats permettent de charger les messages antérieurs. Il n’existe ni bibliothèque manuelle distincte de brouillons ni action d’enregistrement dans le compte.', 'Les nouvelles demandes enregistrent automatiquement le descriptif et la réponse. Les anciennes copies locales ne sont pas importées à votre insu. Conservez sources et vérifications dans les notes de recherche, supprimez les brouillons inutiles et téléchargez les versions finales importantes. Un historique ne prouve pas l’envoi, l’acceptation ou la lecture d’une candidature : tenez vos propres justificatifs.'],
      ['Réutiliser un profil tout en personnalisant le texte', 'Le profil peut conserver nom, compétences, expérience, langue de sortie et ton préférés pour éviter les saisies répétées. Gardez ces données exactes et actuelles, avec des capacités et contributions vérifiables. N’y mettez ni mot de passe, ni numéro d’identité, ni coordonnées bancaires, ni information confidentielle sans rapport.', 'Le profil est un point de départ : adaptez les exemples à chaque opportunité. Actualisez une expérience après la fin d’un cours, poste ou projet afin de ne pas présenter une ancienne situation comme actuelle. Déconnectez-vous sur les appareils partagés ; des brouillons locaux peuvent y rester. Paramètres du compte et stockage du navigateur se gèrent séparément.'],
      ['Gérer les copies enregistrées', 'Supprimer une conversation efface ses messages associés ; le serveur réserve cette action à son propriétaire. Cela n’efface ni téléchargements ni anciennes données locales : utilisez les outils de l’appareil et du navigateur. Vérifiez les messages antérieurs et gardez la version finale nécessaire avant de supprimer.', 'La suppression de l’ensemble du compte se demande au support ; cette version ne propose pas de bouton automatique. Écrivez à support@ailettergen.com depuis l’adresse du compte, sans mot de passe. Paiements et sauvegardes peuvent nécessiter un traitement différent. Nous ne promettons pas un effacement immédiat dans tous les systèmes tiers ; précisez les informations concernées.'],
      ['Transformer votre expérience en exemples utiles', 'Expliquez ce que vous avez fait, dans quel contexte et pourquoi cela compte pour le destinataire. Au lieu d’affirmer bien communiquer, décrivez comment vous avez répondu aux clients ou expliqué un problème. Utilisez des chiffres seulement s’ils sont vérifiables. Projets, bénévolat et études peuvent aussi fournir des exemples.', 'Reliez chaque exigence à un exemple et à son utilité pour l’opportunité. Retenez deux ou trois liens solides puis vérifiez que le texte respecte votre contribution : aider à préparer ne signifie pas diriger un service. Chaque paragraphe doit refléter votre expérience réelle.'],
      ['Ne partager que les informations que vous êtes autorisé à utiliser', 'Un CV ou une capture peut contenir des données d’autrui. Évitez les documents confidentiels d’un employeur, les messages privés ou les candidatures d’un tiers. Décrivez votre contribution à un travail collectif sans vous en attribuer tout le mérite. Citez les exigences dans la mesure nécessaire sans reproduire de longs documents protégés.', 'Vérifiez les personnes, organisations, citations et affirmations du brouillon. Retirez tout détail plausible que vous ne pouvez confirmer. Pour une candidature universitaire, respectez les règles sur l’aide extérieure et l’IA. Le service aide à rédiger honnêtement, pas à usurper une identité ou à présenter une candidature trompeuse.'],
      ['Vérifier les recherches universitaires dans les sources officielles', 'Dates limites, frais, bourses, documents et programmes changent entre les campagnes. Consultez les sources officielles et vérifiez l’année, votre nationalité, le niveau et la modalité d’études. Un résumé d’IA organise les informations mais ne constitue pas une décision d’admission. Une affirmation importante sans source reste à vérifier.', 'Notez l’URL du programme, votre question et les faits confirmés. Distinguez l’exigence publiée de votre interprétation de votre admissibilité. Si deux pages officielles se contredisent, contactez les admissions. Revérifiez dates et frais avant utilisation. L’accès à la recherche dans une offre prévue ne garantit aucune admission.'],
      ['Choisir entre PDF, texte et copie', 'Téléchargez du texte pour poursuivre la rédaction, copiez pour les formulaires ou courriels, et choisissez le PDF si un document à présentation stable est accepté. Suivez les instructions du destinataire et inspectez le fichier réel : sauts de page, signature et caractères non latins.', 'Choisissez un nom de fichier identifiant la candidature sans détails personnels inutiles ni nom d’une autre organisation. Le téléchargement est indépendant du brouillon et de la copie du compte. Après les dernières modifications, exportez à nouveau et joignez la bonne version.'],
      ['Revérifier les informations au fil du temps', 'Fonctions, routes de modèles, tarifs et renseignements universitaires peuvent changer. Distinguez ce qui est disponible de ce qui est prévu et consultez les sources officielles avant de fonder un achat ou une candidature sur une ancienne comparaison ou note.', 'Politique et conditions peuvent évoluer avec le stockage et les fonctions du compte. Si une description contredit l’interface, interrogez le support et évitez les données sensibles inutiles en attendant. Relisez les brouillons lorsque le contexte de la candidature change.'],
    ],
  },
  ru: {
    title: 'Практическое руководство по конфиденциальности данных аккаунта и текстов',
    intro: 'Политика выше описывает сервис. Эти пояснения помогут понять потоки данных и доступные в интерфейсе действия. Они не обещают непроверенных правил хранения у провайдеров и не заменяют их собственные условия конфиденциальности.',
    reference: 'Практический справочник', contents: 'В этом руководстве',
    links: { '/privacy': 'Читать политику конфиденциальности →', '/account': 'Управлять аккаунтом', '/guides': 'Читать руководства →', '/terms': 'Читать условия →', '/features': 'Посмотреть возможности →', '/dashboard': 'Открыть рабочее пространство', '/about': 'О сервисе →' },
    sections: [
      ['Где могут находиться ваши данные', 'Данные формы используются для подготовки запроса к ИИ. Запросы и ответы вошедших пользователей автоматически сохраняются в личной истории; настройки профиля — при их сохранении. Скачанные текстовые файлы и PDF находятся на вашем устройстве. Изменение или удаление одной копии не меняет остальные.', 'Правка ответа не обновляет скачанный PDF и исходный ответ в истории. Скопируйте или экспортируйте изменения до выхода. Исследовательский разговор хранит вопросы, ответы и доступные ссылки, а не исходное резюме, но может включать извлечённый текст вложений. Разговоры остаются в базе до удаления: закрытие браузера их не стирает.'],
      ['Предоставляйте только необходимый личный контекст', 'Для запроса обычно достаточно имени или подписи, подходящего опыта и сведений о возможности. Полный адрес, номер удостоверения и финансовые данные обычно не нужны. Заменяйте лишние сведения кратким описанием. Проверяйте весь файл перед загрузкой, включая старые страницы и комментарии.', 'Краткое описание с убедительными примерами часто полезнее полной неотфильтрованной истории. Оставляйте в профиле только подходящие навыки. В исследовательских заметках храните официальный URL и проверенные наблюдения, а не документы другого кандидата. В отзыве используйте публичное имя и не раскрывайте конфиденциальные детали.'],
      ['Защищайте вводимую информацию', 'Не включайте в запрос номера паспортов, банковские данные, медицинские записи или пароли. Удалите из резюме то, что не хотите передавать провайдеру ИИ, либо используйте краткое описание. Проверяйте снимки экрана на личные адреса и посторонние сообщения.', 'Neon Auth управляет входом, а защищённые API проверяют личность перед чтением или изменением документов. Сервер ограничивает операции владельцем, но абсолютной безопасности не гарантирует ни один сервис. Используйте отдельный пароль, выходите на общих устройствах и защищайте скачанные файлы. Для данных другого человека получите разрешение или исключите их.'],
      ['Отдельно учитывайте обработку сторонними сервисами', 'Провайдеры обеспечивают хостинг, аутентификацию, базу данных, ИИ и криптоплатежи, когда они включены. Маршруты генерации могут использовать Puter и Google Gemini в зависимости от доступного процесса; Neon предоставляет аутентификацию и базу, NOWPayments — обработку платежей. Отправка запроса ИИ и сохранение в истории — разные операции.', 'Изучите условия каждого провайдера: хранение и обучение зависят от сервиса, аккаунта и маршрута. Не предполагайте немедленного удаления всех запросов. Перед отправкой чувствительных данных проверьте договоры обработки и разрешения организации. Краткое описание уменьшает раскрытие; доступность провайдеров может меняться.'],
      ['Управляйте локальными черновиками на общих устройствах', 'Локальные сеансы принадлежат конкретному браузеру и автоматически не синхронизируются между компьютерами. Их может открыть другой человек с тем же профилем браузера. Приватный режим или очистка могут удалить данные; смена браузера не переносит их. Экспортируйте важную работу.', 'История аккаунта позволяет открыть новые запросы и ответы на другом устройстве. Старые локальные черновики автоматически не загружаются и не переносятся; отдельного менеджера сохранённых сеансов нет. Очищайте данные сайта и файлы устройства после сохранения нужных копий. Выход из аккаунта, удаление локальных данных и PDF — разные действия.'],
      ['Храните учётные и платёжные данные в тайне', 'Пароль используется сервисом аутентификации, а не в инструкциях, документах, отзывах или обращениях в поддержку. Браузер получает краткосрочный подписанный токен, который сервер проверяет для доступа к защищённым данным. Действительная личность не даёт доступа к чужим документам: принадлежность ресурсов также проверяется.', 'Никогда не передавайте приватные ключи и фразы восстановления кошелька. Встроенная оплата их не требует. Описывайте ошибку с безопасным номером заказа или снимком, скрывающим секреты. Общедоступный URL аутентификации не равен секретному ключу; секреты провайдеров должны оставаться на сервере вне публичного содержимого и полей.'],
      ['Организуйте разговоры и ответы', 'В названии указывайте организацию или программу и цель. Боковая панель показывает личные разговоры согласно вашему доступу, включая включённые процессы писем и исследований. Открывайте, переименовывайте или продолжайте разговор. Старые разговоры загружаются по двадцать; на странице результата можно загрузить более ранние сообщения. Отдельной ручной библиотеки черновиков и действия сохранения в аккаунт нет.', 'Новые запросы автоматически сохраняют описание и ответ. Старые локальные копии не загружаются незаметно. В исследовательских заметках сохраняйте источники и результаты проверки, удаляйте ненужные черновики и скачивайте важные итоговые документы. История не подтверждает отправку, принятие или прочтение заявки: ведите собственные записи об этом.'],
      ['Используйте профиль, сохраняя индивидуальность письма', 'Профиль может хранить имя, навыки, опыт, предпочтительный язык ответа и тон, чтобы не вводить их повторно. Поддерживайте точность и актуальность, описывайте подтверждаемые способности и вклад. Не храните пароли, номера удостоверений, банковские данные и посторонние конфиденциальные сведения.', 'Профиль — отправная точка: подбирайте примеры под каждую возможность. После завершения курса, работы или проекта обновляйте опыт, чтобы прошлое не выглядело текущим. Выходите на общих устройствах; локальные черновики могут остаться. Настройки аккаунта и хранилище браузера управляются отдельно.'],
      ['Управляйте сохранёнными копиями', 'Удаление разговора удаляет связанные сообщения; сервер разрешает это только владельцу. Скачанные файлы и старые локальные данные остаются: удаляйте их средствами устройства и браузера. Перед удалением проверьте ранние сообщения и сохраните нужную итоговую версию.', 'Полное удаление аккаунта запрашивается через поддержку; автоматической кнопки в этой версии нет. Напишите на support@ailettergen.com с адреса аккаунта без пароля. Платежи и резервные копии могут требовать другой обработки. Мы не обещаем немедленного удаления во всех сторонних системах; уточните, какие данные нужно удалить.'],
      ['Превращайте опыт в убедительные примеры', 'Объясняйте, что вы сделали, в какой ситуации и почему это важно адресату. Вместо заявления о коммуникабельности опишите ответы клиентам или объяснение проблемы. Используйте цифры только при возможности проверки. Проекты, волонтёрство и учёба тоже дают подходящие примеры.', 'Свяжите требование, пример и его пользу для возможности. Выберите две-три сильные связи и проверьте масштаб вклада: помощь в подготовке не должна превращаться в руководство отделом. В каждом абзаце вы должны узнавать свой реальный опыт.'],
      ['Делитесь только тем, что вправе использовать', 'Резюме и снимки могут содержать чужие данные. Не загружайте конфиденциальные документы работодателя, личные сообщения и чужие заявки. Описывайте собственный вклад в совместную работу, не присваивая весь результат. Цитируйте требования по необходимости, не копируя большие защищённые документы.', 'Проверяйте имена, организации, цитаты и факты в черновике. Удаляйте правдоподобные детали, которые нельзя подтвердить. В академических заявках соблюдайте правила внешней помощи и ИИ. Сервис помогает честному письму, а не выдаче себя за другого человека или искажению заявки.'],
      ['Проверяйте сведения об университетах по официальным источникам', 'Сроки, стоимость, стипендии, документы и программы меняются между наборами. Открывайте официальные источники и проверяйте учебный год, гражданство, уровень и форму обучения. Сводка ИИ упорядочивает сведения, но не является решением о приёме. Важное утверждение без источника остаётся непроверенным.', 'Записывайте URL программы, вопрос и подтверждённые факты. Отличайте опубликованное требование от собственной оценки соответствия. При противоречии официальных страниц обращайтесь в приёмную комиссию. Повторно проверяйте даты и стоимость. Доступ к исследованиям в планируемом тарифе не гарантирует поступления.'],
      ['Выбирайте PDF, текст или копирование', 'Скачивайте текст для дальнейшей правки, копируйте для форм и писем, выбирайте PDF, если принимается документ со стабильной вёрсткой. Следуйте инструкциям получателя и проверяйте сам файл: разрывы страниц, подпись и нелатинские символы.', 'Назовите файл так, чтобы определить заявку без лишних личных данных и названия другой организации. Скачанная копия независима от черновика и аккаунта. После окончательных правок экспортируйте заново и приложите правильную версию.'],
      ['Со временем проверяйте сведения повторно', 'Возможности, маршруты моделей, цены и сведения университетов меняются. Различайте доступное и запланированное; перед покупкой или подачей заявки проверяйте официальные источники, а не только старую заметку или сравнение.', 'Политика и условия также могут меняться вместе с хранением и функциями аккаунта. Если описание противоречит интерфейсу, уточните у поддержки и пока не отправляйте лишние чувствительные данные. Пересматривайте черновики при изменении обстоятельств заявки.'],
    ],
  },
  nl: {
    title: 'Praktische privacygids voor accountgegevens en teksten',
    intro: 'Het beleid hierboven beschrijft de dienst. Deze uitleg helpt je de gegevensstromen en de beschikbare keuzes in de interface te begrijpen. Ze belooft geen onbevestigde bewaartermijnen van aanbieders en vervangt hun eigen privacyvoorwaarden niet.',
    reference: 'Praktische naslag', contents: 'In deze gids',
    links: { '/privacy': 'Lees het privacybeleid →', '/account': 'Beheer je account', '/guides': 'Lees de handleidingen →', '/terms': 'Lees de voorwaarden →', '/features': 'Bekijk de functies →', '/dashboard': 'Open de schrijfwerkruimte', '/about': 'Over de dienst →' },
    sections: [
      ['Begrijp waar je gegevens kunnen staan', 'Formuliergegevens worden gebruikt voor een AI-verzoek. Verzoeken en antwoorden van ingelogde gebruikers worden automatisch in de privégeschiedenis opgeslagen; profielvoorkeuren wanneer je ze opslaat. Gedownloade tekstbestanden en PDF’s staan op je apparaat. Eén kopie wijzigen of verwijderen verandert de andere kopieën niet.', 'Een antwoord bewerken wijzigt geen gedownloade PDF of het oorspronkelijke antwoord in de geschiedenis. Kopieer of exporteer wijzigingen voordat je vertrekt. Een onderzoeksgesprek bewaart vragen, antwoorden en beschikbare links, niet het oorspronkelijke cv, maar kan uitgehaalde bijlagetekst bevatten. Gesprekken blijven in de database tot je ze verwijdert: de browser sluiten wist ze niet.'],
      ['Geef alleen de noodzakelijke persoonlijke context', 'Een verzoek vraagt meestal om je naam of ondertekening, relevante ervaring en informatie over de kans, zelden om je volledige adres, identiteitsnummer of financiële gegevens. Vervang onnodige details door een korte omschrijving. Controleer elk volledig bestand voor het uploaden, inclusief oude pagina’s en opmerkingen.', 'Een korte toelichting met sterke voorbeelden helpt vaak meer dan een ongefilterd overzicht. Bewaar alleen relevante vaardigheden in je profiel. Gebruik in onderzoeksnotities officiële URL’s en geverifieerde bevindingen in plaats van documenten van andere kandidaten. Gebruik een openbare weergavenaam voor beoordelingen en laat vertrouwelijke details weg.'],
      ['Bescherm de informatie die je invoert', 'Zet geen paspoortnummers, bankgegevens, medische dossiers of wachtwoorden in je instructies. Verwijder uit je cv wat je niet door een AI-aanbieder wilt laten verwerken of gebruik een samenvatting. Controleer schermafbeeldingen op privé-adressen en berichten die niet relevant zijn.', 'Neon Auth regelt de toegang en beschermde API’s controleren de identiteit voordat ze documenten lezen of wijzigen. De server beperkt handelingen tot de eigenaar, maar geen dienst garandeert perfecte beveiliging. Gebruik een uniek wachtwoord, log uit op gedeelde apparaten en bescherm downloads. Vraag toestemming voor gegevens van anderen of laat ze weg.'],
      ['Beoordeel verwerking door derden afzonderlijk', 'Aanbieders verzorgen hosting, authenticatie, database, AI en cryptobetalingen wanneer die zijn ingeschakeld. Generatieroutes kunnen Puter en Google Gemini gebruiken afhankelijk van het beschikbare proces; Neon levert authenticatie en database, NOWPayments verwerkt betalingen. Een AI-verzoek versturen en iets in de geschiedenis opslaan zijn verschillende handelingen.', 'Lees de voorwaarden van elke aanbieder: bewaring en training hangen af van dienst, account en route. Ga niet uit van onmiddellijke verwijdering bij iedereen. Controleer verwerkersafspraken en toestemming van je organisatie voordat je gevoelige informatie verstuurt. Een korte samenvatting beperkt blootstelling; beschikbaarheid van aanbieders kan veranderen.'],
      ['Beheer lokale concepten op gedeelde apparaten', 'Lokaal opgeslagen sessies horen bij dezelfde browser en synchroniseren niet automatisch tussen computers. Iemand met hetzelfde browserprofiel kan ze mogelijk openen. Privémodus of browseropruiming kan ze verwijderen; een andere browser neemt ze niet over. Exporteer belangrijk werk.', 'De accountgeschiedenis maakt nieuwe verzoeken en antwoorden op andere apparaten toegankelijk. Oude lokale concepten worden niet automatisch geüpload of gemigreerd; er is geen aparte sessiebeheerder. Ruim websitegegevens en apparaatbestanden op nadat je noodzakelijke kopieën hebt bewaard. Uitloggen, lokale gegevens wissen en PDF’s verwijderen zijn afzonderlijke acties.'],
      ['Houd inlog- en betaalgegevens privé', 'Je wachtwoord hoort bij de authenticatiedienst, nooit in instructies, documenten, beoordelingen of supportberichten. De browser ontvangt een kort geldig ondertekend token dat de server controleert voor beschermde gegevens. Een geldige identiteit geeft geen toegang tot andermans documenten: eigendom wordt ook gecontroleerd.', 'Deel nooit privésleutels of herstelzinnen van een cryptowallet. De geïntegreerde betaling vraagt daar niet om. Beschrijf fouten met een niet-gevoelig bestelnummer of een afbeelding waarop inloggegevens verborgen zijn. De openbare authenticatie-URL is geen geheime sleutel; aanbiedergeheimen blijven op de server en buiten openbare inhoud en velden.'],
      ['Organiseer gesprekken en antwoorden', 'Kies een titel met de organisatie of opleiding en het doel. De zijbalk toont privégesprekken volgens je toegangsrechten, waaronder ingeschakelde brief- en onderzoeksprocessen. Open, hernoem of vervolg een gesprek. Oudere gesprekken laden per twintig; resultaten kunnen eerdere berichten laden. Er is geen aparte handmatige conceptbibliotheek of actie om naar je account op te slaan.', 'Nieuwe verzoeken bewaren automatisch de toelichting en het antwoord. Oude lokale kopieën worden niet ongemerkt geüpload. Bewaar bronnen en controles in onderzoeksnotities, verwijder onnodige concepten en download belangrijke eindversies. De geschiedenis bewijst geen verzending, acceptatie of beoordeling van een sollicitatie: houd daarvoor eigen gegevens bij.'],
      ['Hergebruik je profiel en blijf persoonlijk schrijven', 'Het profiel kan naam, vaardigheden, ervaring, voorkeurstaal en toon bewaren, zodat je minder opnieuw typt. Houd gegevens feitelijk en actueel, met aantoonbare vaardigheden en bijdragen. Bewaar geen wachtwoorden, identiteitsnummers, bankgegevens of ongerelateerd vertrouwelijk materiaal.', 'Het profiel is een beginpunt: pas voorbeelden aan elke kans aan. Werk ervaring bij na een cursus, baan of project, zodat oude informatie niet als huidig verschijnt. Log uit op gedeelde apparaten; lokale concepten kunnen achterblijven. Accountinstellingen en browseropslag beheer je afzonderlijk.'],
      ['Beheer de opgeslagen kopieën', 'Een gesprek verwijderen wist de bijbehorende berichten; de server staat dit alleen de eigenaar toe. Downloads en oude lokale gegevens blijven bestaan: verwijder die met apparaat- en browserhulpmiddelen. Controleer eerdere berichten en bewaar een benodigde eindversie voordat je verwijdert.', 'Volledige accountverwijdering vraag je via support aan; deze versie heeft geen automatische knop. Mail support@ailettergen.com vanaf het accountadres zonder je wachtwoord. Betalingen en back-ups kunnen anders worden behandeld. We beloven geen onmiddellijke verwijdering uit alle systemen van derden; benoem welke gegevens je wilt laten verwijderen.'],
      ['Maak je ervaring concreet met voorbeelden', 'Leg uit wat je deed, in welke situatie en waarom dat voor de lezer telt. Beschrijf bijvoorbeeld hoe je klantvragen beantwoordde in plaats van alleen goede communicatie te noemen. Gebruik cijfers alleen als je ze kunt controleren. Projecten, vrijwilligerswerk en studie leveren ook voorbeelden.', 'Verbind elke eis met bewijs en de betekenis voor de kans. Kies twee of drie sterke verbanden en controleer dat je bijdrage niet wordt overdreven: helpen voorbereiden is geen afdeling leiden. Elke alinea moet je werkelijke ervaring weerspiegelen.'],
      ['Deel alleen informatie die je mag gebruiken', 'Een cv of schermafbeelding kan gegevens van anderen bevatten. Vermijd vertrouwelijke werkgeversdocumenten, privéberichten en aanvragen van anderen. Beschrijf je eigen bijdrage aan teamwork zonder het hele resultaat toe te eigenen. Citeer eisen waar nodig zonder grote beschermde documenten over te nemen.', 'Controleer namen, organisaties, citaten en feiten in het concept. Verwijder aannemelijke details die je niet kunt bevestigen. Volg bij studieaanvragen de regels over externe hulp en AI. De dienst ondersteunt eerlijk schrijven, geen identiteitsmisbruik of misleidende aanvragen.'],
      ['Controleer universiteitsonderzoek met officiële bronnen', 'Deadlines, kosten, beurzen, documenten en opleidingen veranderen per ronde. Open officiële bronnen en controleer studiejaar, nationaliteit, niveau en studievorm. Een AI-overzicht helpt informatie ordenen maar is geen toelatingsbesluit. Een belangrijke bewering zonder bron blijft onbevestigd.', 'Noteer de opleidings-URL, je vraag en geverifieerde feiten. Maak onderscheid tussen een gepubliceerde eis en je eigen oordeel of je eraan voldoet. Neem bij tegenstrijdige officiële pagina’s contact op met toelating. Controleer data en kosten opnieuw. Onderzoekstoegang in een gepland pakket garandeert geen toelating.'],
      ['Kies PDF, tekst of kopiëren', 'Download tekst om verder te bewerken, kopieer voor formulieren of e-mail en kies PDF als een document met vaste opmaak wordt geaccepteerd. Volg de instructies van de ontvanger en controleer het echte bestand: pagina-einden, ondertekening en niet-Latijnse tekens.', 'Kies een bestandsnaam die de aanvraag herkenbaar maakt zonder onnodige persoonsgegevens of de naam van een andere organisatie. Een download staat los van het concept en de accountkopie. Exporteer na de laatste wijzigingen opnieuw en voeg de juiste versie toe.'],
      ['Controleer informatie na verloop van tijd opnieuw', 'Functies, modelroutes, prijzen en universiteitsinformatie kunnen veranderen. Onderscheid beschikbare en geplande functies; raadpleeg officiële bronnen voordat je een aankoop of aanvraag baseert op een oude vergelijking of notitie.', 'Beleid en voorwaarden kunnen veranderen met opslag en accountfuncties. Vraag support om uitleg als de beschrijving niet overeenkomt met de interface en verstuur intussen geen onnodige gevoelige gegevens. Herzie concepten wanneer de context van je aanvraag verandert.'],
    ],
  },
  pt: {
    title: 'Guia prático de privacidade para dados da conta e textos',
    intro: 'A política acima descreve o serviço. Estas explicações ajudam a entender os fluxos de dados e as opções disponíveis na interface. Elas não prometem regras de retenção não verificadas nem substituem os termos de privacidade dos provedores.',
    reference: 'Referência prática', contents: 'Neste guia',
    links: { '/privacy': 'Ler a política de privacidade →', '/account': 'Gerenciar sua conta', '/guides': 'Ler os guias →', '/terms': 'Ler os termos →', '/features': 'Ver os recursos →', '/dashboard': 'Abrir o espaço de escrita', '/about': 'Sobre o serviço →' },
    sections: [
      ['Entenda onde seus dados podem existir', 'Os dados do formulário preparam uma solicitação à IA. Solicitações e respostas de usuários conectados são salvas automaticamente no histórico privado; as preferências de perfil são armazenadas quando você as salva. Arquivos de texto e PDF baixados ficam no dispositivo. Alterar ou excluir uma cópia não modifica as demais.', 'Editar uma resposta não atualiza o PDF baixado nem a resposta original no histórico. Copie ou exporte alterações antes de sair. Uma conversa de pesquisa guarda perguntas, respostas e links disponíveis, não o currículo original, mas pode incluir texto extraído dos anexos. As conversas ficam no banco até serem excluídas: fechar o navegador não as apaga.'],
      ['Forneça apenas o contexto pessoal necessário', 'Uma solicitação costuma precisar de nome ou assinatura, experiência relevante e detalhes da oportunidade, raramente de endereço completo, documento de identidade ou informações financeiras. Substitua detalhes desnecessários por um resumo. Revise todo o arquivo antes de enviá-lo, inclusive páginas antigas e comentários.', 'Um resumo breve com exemplos sólidos costuma ajudar mais que um histórico sem filtro. Mantenha apenas habilidades relevantes no perfil. Nas notas de pesquisa, registre a URL oficial e o que verificou, em vez de documentos de outros candidatos. Use um nome público nas avaliações e omita detalhes confidenciais.'],
      ['Proteja as informações que você insere', 'Não inclua números de passaporte, dados bancários, prontuários ou senhas nas instruções. Remova do currículo o que não deseja que um provedor de IA processe ou use um resumo. Verifique capturas para retirar endereços privados e mensagens sem relação com a tarefa.', 'O Neon Auth gerencia o acesso e as APIs protegidas verificam a identidade antes de ler ou alterar documentos. O servidor limita as operações ao proprietário, mas nenhum serviço garante segurança perfeita. Use uma senha exclusiva, saia da conta em dispositivos compartilhados e proteja seus downloads. Peça autorização para incluir dados de outra pessoa ou deixe-os de fora.'],
      ['Considere separadamente o tratamento por terceiros', 'Provedores oferecem hospedagem, autenticação, banco de dados, IA e pagamentos com criptomoedas quando habilitados. As rotas de geração podem usar Puter e Google Gemini conforme o fluxo disponível; o Neon fornece autenticação e banco, e a NOWPayments processa pagamentos. Enviar uma solicitação à IA e salvar no histórico são operações diferentes.', 'Consulte os termos de cada provedor: retenção e treinamento dependem do serviço, da conta e da rota. Não presuma exclusão imediata em todos os casos. Verifique acordos de tratamento ou autorizações da sua organização antes de enviar dados sensíveis. Um resumo reduz a exposição; a disponibilidade dos provedores pode mudar.'],
      ['Gerencie rascunhos locais em dispositivos compartilhados', 'Sessões locais pertencem ao mesmo navegador e não sincronizam automaticamente entre computadores. Quem usa o mesmo perfil pode conseguir abri-las. O modo privado ou a limpeza do navegador pode apagá-las; trocar de navegador não as transfere. Exporte trabalhos importantes.', 'O histórico da conta permite reabrir novas solicitações e respostas em outro dispositivo. Rascunhos locais antigos não são enviados nem migrados automaticamente; não há um gerenciador separado de sessões salvas. Limpe dados do site e arquivos do dispositivo depois de guardar as cópias necessárias. Sair da conta, apagar dados locais e excluir PDF são ações distintas.'],
      ['Mantenha privadas as credenciais de acesso e pagamento', 'Sua senha pertence ao serviço de autenticação, nunca às instruções, documentos, avaliações ou mensagens de suporte. O navegador recebe um token assinado de curta duração, verificado pelo servidor para acessar dados protegidos. Uma identidade válida não permite ler documentos alheios: a propriedade também é verificada.', 'Nunca compartilhe chaves privadas ou frases de recuperação de carteiras. O pagamento integrado não as solicita. Descreva erros com uma referência de pedido não sensível ou uma captura que esconda credenciais. A URL pública de autenticação não é uma chave secreta; segredos de provedores devem ficar no servidor, fora de conteúdo e campos públicos.'],
      ['Organize conversas e respostas', 'Use títulos com a organização ou o programa e a finalidade. A barra lateral mostra conversas privadas conforme seu acesso, incluindo fluxos de cartas e pesquisa habilitados. Abra, renomeie ou continue uma conversa. Conversas antigas carregam em grupos de vinte; os resultados permitem carregar mensagens anteriores. Não há biblioteca manual separada de rascunhos nem ação para salvar na conta.', 'Novas solicitações salvam automaticamente o resumo e a resposta. Cópias locais antigas não são enviadas sem aviso. Registre fontes e verificações nas notas de pesquisa, exclua rascunhos desnecessários e baixe versões finais importantes. O histórico não comprova envio, aceitação ou análise de uma candidatura: mantenha seus próprios registros.'],
      ['Reutilize o perfil sem perder a personalização', 'O perfil pode guardar nome, habilidades, experiência, idioma de saída e tom preferidos para evitar digitação repetida. Mantenha dados exatos e atuais, com capacidades e contribuições demonstráveis. Não guarde senhas, números de documentos, dados bancários ou material confidencial sem relação com o objetivo.', 'O perfil é um ponto de partida: adapte os exemplos a cada oportunidade. Atualize experiências ao concluir cursos, empregos ou projetos para não apresentar informações antigas como atuais. Saia da conta em dispositivos compartilhados; rascunhos locais podem permanecer. Configurações da conta e armazenamento do navegador são gerenciados separadamente.'],
      ['Gerencie as cópias salvas', 'Excluir uma conversa remove as mensagens associadas; o servidor só permite isso ao proprietário. Downloads e dados locais antigos permanecem: apague-os com as ferramentas do dispositivo e navegador. Verifique mensagens anteriores e preserve a versão final necessária antes de excluir.', 'A exclusão de toda a conta é solicitada ao suporte; esta versão não tem botão automático. Escreva para support@ailettergen.com usando o e-mail da conta, sem senha. Pagamentos e backups podem exigir tratamento diferente. Não prometemos exclusão imediata em todos os sistemas de terceiros; informe quais dados deseja remover.'],
      ['Transforme experiência em exemplos úteis', 'Explique o que fez, em qual situação e por que isso importa ao destinatário. Em vez de apenas afirmar boa comunicação, descreva como respondeu a clientes ou explicou um problema. Use números somente se puder verificá-los. Projetos, voluntariado e estudos também oferecem exemplos.', 'Relacione cada requisito a uma evidência e à sua utilidade para a oportunidade. Escolha duas ou três conexões fortes e confira se o texto não exagera sua contribuição: ajudar na preparação não significa liderar um departamento. Cada parágrafo deve refletir sua experiência real.'],
      ['Compartilhe apenas informações que tem direito de usar', 'Um currículo ou captura pode conter dados de outras pessoas. Evite documentos confidenciais de empregadores, mensagens privadas e candidaturas alheias. Descreva sua contribuição ao trabalho coletivo sem se atribuir todo o resultado. Cite requisitos quando necessário sem reproduzir longos documentos protegidos.', 'Revise nomes, organizações, citações e fatos do rascunho. Remova detalhes plausíveis que não consegue confirmar. Em candidaturas acadêmicas, siga as regras sobre ajuda externa e IA. O serviço apoia uma escrita honesta, não a falsidade de identidade ou a apresentação enganosa de uma candidatura.'],
      ['Confira a pesquisa universitária em fontes oficiais', 'Prazos, taxas, bolsas, documentos e programas mudam entre processos seletivos. Abra fontes oficiais e verifique ano acadêmico, nacionalidade, nível e modalidade. Um resumo de IA organiza informações, mas não é uma decisão de admissão. Uma afirmação importante sem fonte continua pendente.', 'Registre a URL do programa, sua pergunta e os fatos verificados. Separe requisitos publicados da sua interpretação sobre atendê-los. Se páginas oficiais divergirem, consulte o setor de admissões. Confira novamente datas e taxas antes de usar. Acesso à pesquisa em um plano previsto não garante admissão.'],
      ['Escolha entre PDF, texto e cópia', 'Baixe texto para continuar editando, copie para formulários ou e-mails e use PDF quando for aceito um documento com apresentação estável. Siga as instruções do destinatário e revise o arquivo real: quebras de página, assinatura e caracteres não latinos.', 'Escolha um nome de arquivo que identifique a candidatura sem dados pessoais desnecessários nem o nome de outra organização. O download é independente do rascunho e da cópia na conta. Após os ajustes finais, exporte novamente e anexe a versão correta.'],
      ['Confira as informações ao longo do tempo', 'Funções, rotas de modelos, preços e informações universitárias podem mudar. Diferencie o disponível do planejado e consulte fontes oficiais antes de basear uma compra ou candidatura em uma comparação ou nota antiga.', 'A política e os termos também podem mudar com o armazenamento e as funções da conta. Se uma descrição não corresponder à interface, consulte o suporte e evite enviar dados sensíveis desnecessários enquanto esclarece. Revise rascunhos quando o contexto da candidatura mudar.'],
    ],
  },
  ar: {
    title: 'دليل عملي لخصوصية بيانات الحساب والكتابة',
    intro: 'تصف السياسة أعلاه الخدمة. تساعدك هذه التوضيحات على فهم مسارات البيانات والخيارات المتاحة في الواجهة. ولا تعد بقواعد احتفاظ غير متحقق منها لدى المزودين، ولا تحل محل شروط الخصوصية الخاصة بهم.',
    reference: 'مرجع عملي', contents: 'في هذا الدليل',
    links: { '/privacy': 'قراءة سياسة الخصوصية ←', '/account': 'إدارة حسابك', '/guides': 'قراءة الأدلة ←', '/terms': 'قراءة الشروط ←', '/features': 'عرض الميزات ←', '/dashboard': 'فتح مساحة الكتابة', '/about': 'عن الخدمة ←' },
    sections: [
      ['تعرّف على الأماكن التي قد توجد فيها بياناتك', 'تُستخدم بيانات النموذج لإعداد طلب إلى الذكاء الاصطناعي. تُحفظ طلبات المستخدمين المسجلين وردودها تلقائيًا في السجل الخاص، وتُحفظ تفضيلات الملف الشخصي عند حفظها. تبقى ملفات النص وPDF التي تنزّلها على جهازك. لا يؤدي تغيير نسخة أو حذفها إلى تغيير النسخ الأخرى.', 'تعديل الرد لا يحدّث ملف PDF المنزّل ولا الرد الأصلي في السجل. انسخ تعديلاتك أو صدّرها قبل المغادرة. تحتفظ محادثة البحث بالأسئلة والردود والروابط المتاحة، لا بملف السيرة الأصلي، لكنها قد تتضمن النص المستخرج من المرفقات. تبقى المحادثات في قاعدة البيانات حتى تحذفها؛ إغلاق المتصفح لا يمحوها.'],
      ['قدّم الحد الأدنى اللازم من المعلومات الشخصية', 'يحتاج الطلب عادة إلى اسمك أو توقيعك والخبرة ذات الصلة وتفاصيل الفرصة، ولا يحتاج غالبًا إلى عنوانك الكامل أو رقم هويتك أو معلوماتك المالية. استبدل التفاصيل غير اللازمة بوصف موجز. افحص الملف كاملًا قبل رفعه، بما في ذلك الصفحات القديمة والتعليقات.', 'قد يكون الوصف المختصر بأمثلة واضحة أنفع من سجل كامل غير منقّح. احتفظ بالمهارات المناسبة فقط في ملفك. وفي ملاحظات البحث، احفظ الرابط الرسمي وما تحققت منه بدل مستندات متقدم آخر. استخدم اسم عرض عامًا للتقييمات واحذف التفاصيل السرية.'],
      ['احمِ المعلومات التي تختار إدخالها', 'لا تضع أرقام جوازات السفر أو البيانات البنكية أو السجلات الطبية أو كلمات المرور في تعليمات الإنشاء. احذف من السيرة ما لا تريد أن يعالجه مزود الذكاء الاصطناعي أو استخدم ملخصًا. راجع لقطات الشاشة لإزالة العناوين الخاصة والرسائل غير المرتبطة بالمهمة.', 'تدير Neon Auth الوصول، وتتحقق الواجهات المحمية من الهوية قبل قراءة المستندات أو تعديلها. يقصر الخادم العمليات على المالك، لكن لا توجد خدمة تضمن أمنًا مثاليًا. استخدم كلمة مرور فريدة وسجّل الخروج على الأجهزة المشتركة واحمِ تنزيلاتك. استأذن قبل تضمين بيانات شخص آخر أو استبعدها.'],
      ['انظر إلى معالجة الجهات الخارجية بشكل منفصل', 'تقدم جهات خارجية الاستضافة والمصادقة وقاعدة البيانات والذكاء الاصطناعي والدفع بالعملات المشفرة عند تفعيله. قد تستخدم مسارات الإنشاء Puter وGoogle Gemini بحسب المسار المتاح؛ توفر Neon المصادقة وقاعدة البيانات وتعالج NOWPayments المدفوعات. إرسال طلب للذكاء الاصطناعي وحفظه في السجل عمليتان مختلفتان.', 'راجع شروط كل مزود؛ فالاحتفاظ والتدريب يعتمدان على الخدمة والحساب والمسار. لا تفترض حذف جميع الطلبات فورًا. تحقق من اتفاقيات المعالجة أو موافقة مؤسستك قبل إرسال معلومات حساسة. يقلل الملخص من التعرض، وقد يتغير توفر المزودين.'],
      ['أدِر المسودات المحلية على الأجهزة المشتركة', 'تنتمي الجلسات المحلية إلى المتصفح نفسه ولا تتزامن تلقائيًا بين الأجهزة. قد يستطيع مستخدم ملف المتصفح نفسه فتحها. قد يحذفها التصفح الخاص أو تنظيف المتصفح، ولا ينقلها تغيير المتصفح. صدّر العمل المهم.', 'يتيح سجل الحساب فتح الطلبات والردود الجديدة على جهاز آخر. لا تُرفع المسودات المحلية القديمة ولا تُنقل تلقائيًا، ولا يوجد مدير منفصل للجلسات المحفوظة. نظّف بيانات الموقع وملفات الجهاز بعد حفظ النسخ اللازمة. تسجيل الخروج وحذف البيانات المحلية وحذف PDF إجراءات منفصلة.'],
      ['حافظ على سرية بيانات الدخول والدفع', 'تُستخدم كلمة مرورك في خدمة المصادقة، ولا توضع في التعليمات أو المستندات أو التقييمات أو رسائل الدعم. يحصل المتصفح على رمز موقّع قصير الصلاحية يتحقق منه الخادم للوصول إلى البيانات المحمية. الهوية الصحيحة لا تبيح قراءة مستندات الآخرين؛ إذ تُفحص ملكية الموارد أيضًا.', 'لا تشارك المفاتيح الخاصة أو عبارات استعادة المحافظ مطلقًا. لا يطلب الدفع المدمج هذه العبارات. صِف الأخطاء بمرجع طلب غير حساس أو لقطة تخفي بيانات الدخول. رابط المصادقة العام ليس مفتاحًا سريًا؛ يجب أن تبقى أسرار المزودين على الخادم وخارج المحتوى والحقول العامة.'],
      ['نظّم المحادثات والردود', 'اختر عنوانًا يوضح المؤسسة أو البرنامج والغرض. يعرض الشريط الجانبي المحادثات الخاصة حسب صلاحياتك، بما فيها مسارات الخطابات والبحث المفعّلة. افتح المحادثة أو أعد تسميتها أو تابعها. تُحمّل المحادثات الأقدم على دفعات من عشرين، ويمكن تحميل الرسائل السابقة في النتائج. لا توجد مكتبة يدوية منفصلة للمسودات ولا إجراء لحفظها في الحساب.', 'تحفظ الطلبات الجديدة الموجز والرد تلقائيًا. لا تُرفع النسخ المحلية القديمة دون علمك. احتفظ بالمصادر والتحققات في ملاحظات البحث واحذف المسودات غير اللازمة ونزّل النسخ النهائية المهمة. لا يثبت السجل إرسال طلب أو قبوله أو مراجعته؛ احتفظ بسجلاتك الخاصة لهذه الأحداث.'],
      ['أعد استخدام ملفك مع تخصيص كل خطاب', 'يمكن للملف حفظ الاسم والمهارات والخبرة ولغة الإخراج والأسلوب المفضل لتجنب تكرار الكتابة. حافظ على دقتها وحداثتها، واستخدم قدرات ومساهمات يمكن إثباتها. لا تحفظ كلمات مرور أو أرقام هوية أو بيانات بنكية أو مواد سرية غير مرتبطة بالغرض.', 'الملف نقطة بداية؛ عدّل الأمثلة لكل فرصة. حدّث الخبرة بعد انتهاء دورة أو وظيفة أو مشروع كي لا تبدو المعلومات القديمة حالية. سجّل الخروج من الأجهزة المشتركة؛ فقد تبقى عليها مسودات محلية. تُدار إعدادات الحساب وتخزين المتصفح بصورة منفصلة.'],
      ['أدِر النسخ التي حفظتها', 'يحذف حذف المحادثة رسائلها المرتبطة، ولا يسمح الخادم بذلك إلا لمالكها. تبقى التنزيلات والبيانات المحلية القديمة؛ احذفها بأدوات الجهاز والمتصفح. راجع الرسائل السابقة واحتفظ بالنسخة النهائية اللازمة قبل الحذف.', 'يُطلب حذف الحساب بالكامل عبر الدعم؛ لا يوجد زر آلي في هذا الإصدار. راسل support@ailettergen.com من بريد الحساب دون كلمة مرورك. قد تحتاج سجلات الدفع والنسخ الاحتياطية إلى معالجة مختلفة. لا نعد بحذف فوري من جميع أنظمة الجهات الخارجية؛ حدد المعلومات التي تريد حذفها.'],
      ['حوّل خبرتك إلى أمثلة مفيدة', 'اشرح ما فعلته وفي أي ظرف ولماذا يهم القارئ. بدل القول إن تواصلك ممتاز، صِف كيف أجبت عن أسئلة العملاء أو شرحت مشكلة. استخدم الأرقام فقط إن أمكن التحقق منها. قد توفر المشاريع والتطوع والدراسة أمثلة مناسبة أيضًا.', 'اربط كل متطلب بدليل وفائدته للفرصة. اختر رابطين أو ثلاثة أقوياء وتحقق من عدم تضخيم مساهمتك؛ فالمساعدة في الإعداد لا تعني قيادة قسم. يجب أن تعكس كل فقرة خبرتك الحقيقية.'],
      ['شارك فقط المعلومات التي يحق لك استخدامها', 'قد تحتوي السيرة أو لقطة الشاشة على بيانات الآخرين. تجنب مستندات صاحب العمل السرية والرسائل الخاصة وطلبات الآخرين. صِف مساهمتك في العمل الجماعي دون نسبة النتيجة كلها لنفسك. اقتبس المتطلبات عند الحاجة دون نسخ مستندات محمية طويلة.', 'راجع الأسماء والمؤسسات والاقتباسات والوقائع في المسودة. احذف التفاصيل المعقولة ظاهريًا التي لا تستطيع تأكيدها. في الطلبات الأكاديمية، اتبع قواعد المؤسسة بشأن المساعدة الخارجية والذكاء الاصطناعي. تدعم الخدمة الكتابة الصادقة، لا انتحال الهوية أو تقديم طلب مضلل.'],
      ['تحقق من البحث الجامعي عبر المصادر الرسمية', 'تتغير المواعيد والرسوم والمنح والمستندات والبرامج بين دورات التقديم. افتح المصادر الرسمية وتحقق من العام الدراسي والجنسية والمستوى ونمط الدراسة. ينظّم ملخص الذكاء الاصطناعي المعلومات لكنه ليس قرار قبول. تبقى المعلومة المهمة بلا مصدر غير متحقق منها.', 'دوّن رابط البرنامج وسؤالك والحقائق التي تحققت منها. ميّز بين متطلب منشور وتفسيرك لاستيفائه. إذا تعارضت صفحتان رسميتان، تواصل مع مكتب القبول. أعد فحص المواعيد والرسوم قبل الاعتماد عليها. لا يضمن الوصول إلى البحث ضمن باقة مخطط لها القبول.'],
      ['اختر بين PDF والنص والنسخ', 'نزّل النص لمتابعة التعديل، وانسخ للنماذج أو البريد، واختر PDF عندما يُقبل مستند بتنسيق ثابت. اتبع تعليمات المستلم وافحص الملف الفعلي، بما في ذلك فواصل الصفحات والتوقيع والأحرف غير اللاتينية.', 'اختر اسم ملف يحدد الطلب دون بيانات شخصية زائدة أو اسم مؤسسة أخرى. التنزيل نسخة مستقلة عن المسودة ونسخة الحساب. بعد التعديلات النهائية، صدّر مجددًا وأرفق الإصدار الصحيح.'],
      ['أعد التحقق من المعلومات مع مرور الوقت', 'قد تتغير الميزات ومسارات النماذج والأسعار والمعلومات الجامعية. ميّز بين المتاح والمخطط له وراجع المصادر الرسمية قبل بناء شراء أو طلب على مقارنة أو ملاحظة قديمة.', 'قد تتغير السياسة والشروط أيضًا مع التخزين وميزات الحساب. إذا خالف الوصف الواجهة، استفسر من الدعم وتجنب إرسال معلومات حساسة غير لازمة حتى يتضح الأمر. راجع المسودات عندما يتغير سياق الطلب.'],
    ],
  },
};

export function privacyGuideCopy(locale: Locale) {
  const original = articleSections('/privacy');
  if (locale === 'en') return {
    ...pageArticles['/privacy'], sections: original,
    reference: 'Practical reference', contents: 'In this guide',
    links: { '/privacy': 'Read privacy →', '/account': 'Manage your writing account', '/guides': 'Read guides →', '/terms': 'Read terms →', '/features': 'Read features →', '/dashboard': 'Open the writing workspace', '/about': 'Read about →' } as Record<string, string>,
  };
  const copy = copies[locale];
  return {
    ...copy,
    sections: original.map((section, index) => {
      const [title, ...paragraphs] = copy.sections[index];
      return { ...section, title, paragraphs };
    }),
  };
}
